{"rob": "robolang 1.3;

task relocate_part(robot r, object p, location src, location dst) {
    pre { object_at p src; }
    goal { object_at p dst; }
    plan {
        move r to src;
        grasp r p;
        move r to dst;
        place r p at dst;
    }
}
